//
// Subworkflow that uses the nf-schema plugin to validate parameters and render the parameter summary
//

include { paramsSummaryLog   } from 'plugin/nf-schema'
include { validateParameters } from 'plugin/nf-schema'
include { paramsHelp         } from 'plugin/nf-schema'

workflow UTILS_NFSCHEMA_PLUGIN {

    take:
    input_workflow      // workflow: the workflow object used by nf-schema to get metadata from the workflow
    validate_params     // boolean:  validate the parameters
    parameters_schema   // string:   path to the parameters JSON schema.
                        //           this has to be the same as the schema given to `validation.parametersSchema`
                        //           when this input is empty it will automatically use the configured schema or
                        //           "${projectDir}/nextflow_schema.json" as default. This input should not be empty
                        //           for meta pipelines
    help                // boolean:  show help message
    help_full           // boolean:  show full help message
    show_hidden         // boolean:  show hidden parameters in help message
    before_text         // string:   text to show before the help message and parameters summary
    after_text          // string:   text to show after the help message and parameters summary
    command             // string:   an example command of the pipeline
    cli_typecast        // boolean:  whether to perform typecasting of CLI parameters. Set this to `null` to use the default behaviour

    main:

    if(help || help_full) {
        help_options = [
            parameter: (help instanceof String && help != "true") ? help : null,
            beforeText: before_text,
            afterText: after_text,
            command: command,
            showHidden: show_hidden,
            fullHelp: help_full,
        ]
        if(parameters_schema) {
            help_options << [parameters_schema: parameters_schema]
        }

        log.info paramsHelp(help_options)
        exit 0
    }

    //
    // Print parameter summary to stdout. This will display the parameters
    // that differ from the default given in the JSON schema
    //

    summary_options = [:]
    if(parameters_schema) {
        summary_options << [parameters_schema: parameters_schema]
    }
    log.info before_text
    log.info paramsSummaryLog(summary_options)
    log.info after_text

    //
    // Validate the parameters using nextflow_schema.json or the schema
    // given via the validation.parametersSchema configuration option
    //
    if(validate_params) {
        validateOptions = [:]
        if(parameters_schema) {
            validateOptions << [parameters_schema: parameters_schema]
        }
        if(cli_typecast != null) {
            validateOptions << [cast_cli_params: cli_typecast]
        }
        validateParameters(validateOptions)
    }

    emit:
    dummy_emit = true
}

nextflow_workflow {

    name "Test Subworkflow UTILS_NFSCHEMA_PLUGIN"
    script "../main.nf"
    workflow "UTILS_NFSCHEMA_PLUGIN"

    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "subworkflows/utils_nfschema_plugin"
    tag "plugin/nf-schema"

    config "./nextflow.config"

    test("Should run nothing") {

        when {

            params {
                test_data   = ''
            }

            workflow {
                """
                validate_params = false
                input[0] = workflow
                input[1] = validate_params
                input[2] = ""
                input[3] = false
                input[4] = false
                input[5] = false
                input[6] = ""
                input[7] = ""
                input[8] = ""
                input[9] = null
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success }
            )
        }
    }

    test("Should validate params") {

        when {

            params {
                test_data   = ''
                outdir      = null
            }

            workflow {
                """
                validate_params = true
                input[0] = workflow
                input[1] = validate_params
                input[2] = ""
                input[3] = false
                input[4] = false
                input[5] = false
                input[6] = ""
                input[7] = ""
                input[8] = ""
                input[9] = null
                """
            }
        }

        then {
            assertAll(
                { assert workflow.failed },
                { assert (workflow.stdout + workflow.stderr).any { it.contains('ERROR ~ Validation of pipeline parameters failed!') } }
            )
        }
    }

    test("Should run nothing - custom schema") {

        when {

            params {
                test_data   = ''
            }

            workflow {
                """
                validate_params = false
                input[0] = workflow
                input[1] = validate_params
                input[2] = "${projectDir}/subworkflows/nf-core/utils_nfschema_plugin/tests/nextflow_schema.json"
                input[3] = false
                input[4] = false
                input[5] = false
                input[6] = ""
                input[7] = ""
                input[8] = ""
                input[9] = null
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success }
            )
        }
    }

    test("Should validate params - custom schema") {

        when {

            params {
                test_data   = ''
                outdir      = null
            }

            workflow {
                """
                validate_params = true
                input[0] = workflow
                input[1] = validate_params
                input[2] = "${projectDir}/subworkflows/nf-core/utils_nfschema_plugin/tests/nextflow_schema.json"
                input[3] = false
                input[4] = false
                input[5] = false
                input[6] = ""
                input[7] = ""
                input[8] = ""
                input[9] = null
                """
            }
        }

        then {
            assertAll(
                { assert workflow.failed },
                { assert (workflow.stdout + workflow.stderr).any { it.contains('ERROR ~ Validation of pipeline parameters failed!') } }
            )
        }
    }

    test("Should create a help message") {

        when {

            params {
                test_data   = ''
                outdir      = null
            }

            workflow {
                """
                validate_params = true
                input[0] = workflow
                input[1] = validate_params
                input[2] = "${projectDir}/subworkflows/nf-core/utils_nfschema_plugin/tests/nextflow_schema.json"
                input[3] = true
                input[4] = false
                input[5] = false
                input[6] = "Before"
                input[7] = "After"
                input[8] = "nextflow run test/test"
                input[9] = null
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success }
            )
        }
    }
}

plugins {
    id "nf-schema@3.0.0"
}

validation {
    parametersSchema = "${projectDir}/subworkflows/nf-core/utils_nfschema_plugin/tests/nextflow_schema.json"
    monochromeLogs = true
}

{
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "$id": "https://raw.githubusercontent.com/./master/nextflow_schema.json",
    "title": ". pipeline parameters",
    "description": "",
    "type": "object",
    "$defs": {
        "input_output_options": {
            "title": "Input/output options",
            "type": "object",
            "fa_icon": "fas fa-terminal",
            "description": "Define where the pipeline should find input data and save output data.",
            "required": ["outdir"],
            "properties": {
                "validate_params": {
                    "type": "boolean",
                    "description": "Validate parameters?",
                    "default": true,
                    "hidden": true
                },
                "outdir": {
                    "type": "string",
                    "format": "directory-path",
                    "description": "The output directory where the results will be saved. You have to use absolute paths to storage on Cloud infrastructure.",
                    "fa_icon": "fas fa-folder-open"
                },
                "test_data_base": {
                    "type": "string",
                    "default": "https://raw.githubusercontent.com/nf-core/test-datasets/modules",
                    "description": "Base for test data directory",
                    "hidden": true
                },
                "test_data": {
                    "type": "string",
                    "description": "Fake test data param",
                    "hidden": true
                }
            }
        },
        "generic_options": {
            "title": "Generic options",
            "type": "object",
            "fa_icon": "fas fa-file-import",
            "description": "Less common options for the pipeline, typically set in a config file.",
            "help_text": "These options are common to all nf-core pipelines and allow you to customise some of the core preferences for how the pipeline runs.\n\nTypically these options would be set in a Nextflow config file loaded for all pipeline runs, such as `~/.nextflow/config`.",
            "properties": {
                "help": {
                    "type": "boolean",
                    "description": "Display help text.",
                    "fa_icon": "fas fa-question-circle",
                    "hidden": true
                },
                "version": {
                    "type": "boolean",
                    "description": "Display version and exit.",
                    "fa_icon": "fas fa-question-circle",
                    "hidden": true
                },
                "logo": {
                    "type": "boolean",
                    "default": true,
                    "description": "Display nf-core logo in console output.",
                    "fa_icon": "fas fa-image",
                    "hidden": true
                },
                "singularity_pull_docker_container": {
                    "type": "boolean",
                    "description": "Pull Singularity container from Docker?",
                    "hidden": true
                },
                "publish_dir_mode": {
                    "type": "string",
                    "default": "copy",
                    "description": "Method used to save pipeline results to output directory.",
                    "help_text": "The Nextflow `publishDir` option specifies which intermediate files should be saved to the output directory. This option tells the pipeline what method should be used to move these files. See [Nextflow docs](https://www.nextflow.io/docs/latest/process.html#publishdir) for details.",
                    "fa_icon": "fas fa-copy",
                    "enum": ["symlink", "rellink", "link", "copy", "copyNoFollow", "move"],
                    "hidden": true
                },
                "monochrome_logs": {
                    "type": "boolean",
                    "description": "Use monochrome_logs",
                    "hidden": true
                }
            }
        }
    },
    "allOf": [
        {
            "$ref": "#/$defs/input_output_options"
        },
        {
            "$ref": "#/$defs/generic_options"
        }
    ]
}
